const https = require("https");
const fs = require("fs");
const version = "{{MC_VERSION}}";

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { "user-agent": "terrypanel" } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        return get(res.headers.location).then(resolve, reject);
      }
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    }).on("error", reject);
  });
}

(async () => {
  const manifest = JSON.parse((await get("https://piston-meta.mojang.com/mc/game/version_manifest_v2.json")).body.toString("utf8"));
  const entry = manifest.versions.find((v) => v.id === version) || manifest.latest;
  const metaUrl = entry && entry.url ? entry.url : manifest.versions[0].url;
  const meta = JSON.parse((await get(metaUrl)).body.toString("utf8"));
  console.log(`Downloading vanilla ${meta.id} server`);
  const jar = await get(meta.downloads.server.url);
  if (jar.status !== 200) throw new Error(`Vanilla download returned ${jar.status}`);
  fs.writeFileSync("server.jar", jar.body);
  console.log(`Saved server.jar (${(jar.body.length / 1024 / 1024).toFixed(1)} MB)`);
})().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
